INSERT INTO `khayah_posts` VALUES("3427", "1", "2020-12-09 18:32:17", "2020-12-09 09:32:17", "<a href=\"http://khayah.org/khayah/wp-content/uploads/2020/12/카야-소식지-전체-고용량_20201203최종.pdf\">2017-2020 카야 소식지 Vol. 1</a>\n\n<span style=\"color: #ffffff;\">[ ]</span>\n\n[hr height=\"20\" style=\"default\" line=\"default\" themecolor=\"0\"][button title=\"목록으로\" link=\"/khayah/사업/진행사업/\" icon=\"icon-right-open\" icon_position=\"right\" size=\"2\" onclick=\"javascript:window.history.back();\"]\n<!-- // -->", "2017-2020 카야 소식지 Vol.1", "", "inherit", "closed", "closed", "", "3321-revision-v1", "", "", "2020-12-09 18:32:17", "2020-12-09 09:32:17", "", "3321", "http://khayah.org/khayah/3321-revision-v1/", "0", "revision", "", "0");
