INSERT INTO `khayah_posts` VALUES("4157", "1", "2024-07-19 09:49:30", "2024-07-19 00:49:30", "", "사전OT 온라인ZOOM 백드롭", "", "inherit", "closed", "closed", "", "%ec%82%ac%ec%a0%84ot-%ec%98%a8%eb%9d%bc%ec%9d%b8zoom-%eb%b0%b1%eb%93%9c%eb%a1%ad", "", "", "2024-07-19 09:49:30", "2024-07-19 00:49:30", "", "4155", "http://khayah.org/khayah/wp-content/uploads/2024/07/사전OT-온라인ZOOM-백드롭.jpg", "0", "attachment", "image/jpeg", "0");
INSERT INTO `khayah_posts` VALUES("4158", "1", "2024-07-19 09:49:45", "2024-07-19 00:49:45", "", "경기청년 기후특사단 최종 합격자 및 예비합격자 (안내문)", "", "inherit", "closed", "closed", "", "%ea%b2%bd%ea%b8%b0%ec%b2%ad%eb%85%84-%ea%b8%b0%ed%9b%84%ed%8a%b9%ec%82%ac%eb%8b%a8-%ec%b5%9c%ec%a2%85-%ed%95%a9%ea%b2%a9%ec%9e%90-%eb%b0%8f-%ec%98%88%eb%b9%84%ed%95%a9%ea%b2%a9%ec%9e%90-%ec%95%88", "", "", "2024-07-19 09:49:45", "2024-07-19 00:49:45", "", "4155", "http://khayah.org/khayah/wp-content/uploads/2024/07/경기청년-기후특사단-최종-합격자-및-예비합격자-안내문.pdf", "0", "attachment", "application/pdf", "0");
INSERT INTO `khayah_posts` VALUES("4159", "1", "2024-07-19 09:49:54", "2024-07-19 00:49:54", "<!-- wp:paragraph -->\n<p>안녕하세요, 카야인터내셔널 입니다.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>2024년 경기청년 기후특사단 모집에 많은 관심과 참여에 깊은 감사의 말씀을 드립니다.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>최종 합격을 축하드리며, 합격자 명단 및 사전OT 사항을 안내드리니 첨부된 파일을 반드시 확인하시기 바랍니다.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>[</strong><strong>최종합격자 안내</strong><strong>]</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o 대 상 : 첨부된 명단 참조</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>  ※ 합격을 포기하는 지원자분들은 “카야인터내셔널 카카오톡” 또는 “이메일(<a href=\"mailto:khayahinternational@gmail.com\">khayahinternational@gmail.com</a>)”로 성함/연락처/사유를 연락주시기 바랍니다.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o <strong>사전설문지 등록</strong><strong>(2024.7.19.(</strong><strong>금</strong><strong>)12:00</strong><strong>까지</strong><strong>)</strong> : https://forms.gle/nKnak6g96DM17vQP8</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o 주요 추진일정</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":4156} -->\n<figure class=\"wp-block-image\"><img src=\"http://khayah.org/khayah/wp-content/uploads/2024/07/image.png\" alt=\"\" class=\"wp-image-4156\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>[</strong><strong>사전</strong><strong>OT </strong><strong>안내</strong><strong>]</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o 대 상 : 최종 합격자 및 예비합격자(첨부된 명단 참조) 144명 (필수 참석 / 미참여자는 자동 합격 취소)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o 일 시 :<strong> </strong><strong>2024. 7. 19.(</strong><strong>금</strong><strong>) 16:00</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o 장 소 : 온라인 ZOOM</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>o 링 크</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:table -->\n<table class=\"wp-block-table\"><tbody><tr><td>ZOOM 회의 링크</td><td><a href=\"https://us06web.zoom.us/j/88980322672\">https://us06web.zoom.us/j/88980322672</a> </td></tr><tr><td>ZOOM 회의 ID 및 PW</td><td>회의 ID: 889 8032 2672  /  암호: 435881</td></tr></tbody></table>\n<!-- /wp:table -->\n\n<!-- wp:paragraph -->\n<p>o 준 비</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>  1. 배경화면 : 아래 첨부된 백드롭 이미지를 배경화면으로 설정해 주시기 바랍니다.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>  2. 참석자 이름 : 국가/이름 (ex. 우즈베키스탄/홍길동) </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>  3. 비디오 ON, 오디오 OFF 상태로 입장</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>다시 한번 합격을 축하드립니다.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>감사합니다. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>카야인터내셔널 드림.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:file {\"id\":4157,\"href\":\"http://khayah.org/khayah/wp-content/uploads/2024/07/사전OT-온라인ZOOM-백드롭.jpg\"} -->\n<div class=\"wp-block-file\"><a href=\"http://khayah.org/khayah/wp-content/uploads/2024/07/사전OT-온라인ZOOM-백드롭.jpg\">사전OT 온라인ZOOM 백드롭</a><a href=\"http://khayah.org/khayah/wp-content/uploads/2024/07/사전OT-온라인ZOOM-백드롭.jpg\" class=\"wp-block-file__button\" download>다운로드</a></div>\n<!-- /wp:file -->\n\n<!-- wp:file {\"id\":4158,\"href\":\"http://khayah.org/khayah/wp-content/uploads/2024/07/경기청년-기후특사단-최종-합격자-및-예비합격자-안내문.pdf\"} -->\n<div class=\"wp-block-file\"><a href=\"http://khayah.org/khayah/wp-content/uploads/2024/07/경기청년-기후특사단-최종-합격자-및-예비합격자-안내문.pdf\">경기청년 기후특사단 최종 합격자 및 예비합격자 (안내문)</a><a href=\"http://khayah.org/khayah/wp-content/uploads/2024/07/경기청년-기후특사단-최종-합격자-및-예비합격자-안내문.pdf\" class=\"wp-block-file__button\" download>다운로드</a></div>\n<!-- /wp:file -->", "2024년 경기청년 기후특사단 최종합격자 발표 및 사전OT 안내", "", "inherit", "closed", "closed", "", "4155-revision-v1", "", "", "2024-07-19 09:49:54", "2024-07-19 00:49:54", "", "4155", "http://khayah.org/khayah/4155-revision-v1/", "0", "revision", "", "0");
