INSERT INTO `khayah_posts` VALUES("4249", "1", "2024-11-19 02:14:47", "2024-11-18 17:14:47", "<!-- wp:image {\"id\":4232} -->\n<figure class=\"wp-block-image\"><img src=\"http://khayah.org/khayah/wp-content/uploads/2024/11/001-1024x1024.png\" alt=\"\" class=\"wp-image-4232\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4233} -->\n<figure class=\"wp-block-image\"><img src=\"http://khayah.org/khayah/wp-content/uploads/2024/11/002-1024x1024.png\" alt=\"\" class=\"wp-image-4233\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4234} -->\n<figure class=\"wp-block-image\"><img src=\"http://khayah.org/khayah/wp-content/uploads/2024/11/003-1024x1024.png\" alt=\"\" class=\"wp-image-4234\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4235} -->\n<figure class=\"wp-block-image\"><img src=\"http://khayah.org/khayah/wp-content/uploads/2024/11/004-1024x1024.png\" alt=\"\" class=\"wp-image-4235\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:gallery {\"ids\":[4248]} -->\n<ul class=\"wp-block-gallery columns-1 is-cropped\"><li class=\"blocks-gallery-item\"><figure><img src=\"http://khayah.org/khayah/wp-content/uploads/2024/11/디자인-홍보마케팅-채용-24_11-005-1024x1024.png\" alt=\"\" data-id=\"4248\" data-link=\"http://khayah.org/khayah/%eb%aa%a8%ec%a7%91%ea%b3%b5%ea%b3%a0-2022%eb%85%84%eb%8f%84-%ed%95%98%eb%b0%98%ea%b8%b0-koica-oda-%ec%98%81%ed%94%84%eb%a1%9c%ed%8e%98%ec%85%94%eb%84%90yp-%eb%aa%a8%ec%a7%91-7-17-2-2-2-3-2-2-2-2/%eb%94%94%ec%9e%90%ec%9d%b8-%ed%99%8d%eb%b3%b4%eb%a7%88%ec%bc%80%ed%8c%85-%ec%b1%84%ec%9a%a9-24_11-005/\" class=\"wp-image-4248\"/></figure></li></ul>\n<!-- /wp:gallery -->\n\n<!-- wp:file {\"id\":4236,\"href\":\"http://khayah.org/khayah/wp-content/uploads/2024/11/카야인터내셔널-입사지원서-양식_홍보마케팅-분야-1.docx\"} -->\n<div class=\"wp-block-file\"><a href=\"http://khayah.org/khayah/wp-content/uploads/2024/11/카야인터내셔널-입사지원서-양식_홍보마케팅-분야-1.docx\">[카야인터내셔널] 입사지원서 양식_홍보마케팅 분야</a><a href=\"http://khayah.org/khayah/wp-content/uploads/2024/11/카야인터내셔널-입사지원서-양식_홍보마케팅-분야